/**
 * Simulation coverage audit: one row per catalogue component — 3D model, electrical model, functional
 * simulation, validation and the functional self-test result. Generated by `npm run sim:coverage` into
 * src/data/sim-coverage.generated.json (shown on /library/coverage) and checked by tests/sim/coverage.test.ts.
 */
import { allComponents } from "@/lib/catalogue";
import { modelKeyFor } from "@/lib/models/modelKey";
import { selfTest, type SelfTestStatus } from "@/lib/sim/selftest";
import { supportOf, type SupportLevel } from "./support";
import type { ComponentRecord } from "@/lib/types";

export interface CoverageRow {
  id: string;
  name: string;
  kind: ComponentRecord["kind"];
  category: string;
  level: SupportLevel;
  summary: string;
  limits: string[];
  alternative: string | null;
  /** "exact" = a model of this part, "family" = a family/generic stand-in, "block" = plain block */
  model3d: "exact" | "family" | "block";
  model3dLabel: string;
  electrical: boolean;
  functional: boolean;
  validation: boolean;
  selftest: SelfTestStatus;
  selftestDetail: string;
}

const MECH = new Set(["wheel", "caster", "chassis", "mechanical", "fastener", "material", "pcb", "tool", "connector"]);

export function coverageRow(c: ComponentRecord): CoverageRow {
  const s = supportOf(c);
  const m = modelKeyFor(c);
  const t = selfTest(c);
  return {
    id: c.id,
    name: c.name,
    kind: c.kind,
    category: c.category,
    level: s.level,
    summary: s.summary,
    limits: s.limits,
    alternative: s.alternative?.name ?? null,
    model3d: m.key === "generic" ? "block" : m.exact ? "exact" : "family",
    model3dLabel: m.label,
    electrical: c.pins.length > 0 && !MECH.has(c.kind),
    functional: s.level === "full",
    validation: c.pins.length > 0,
    selftest: t.status,
    selftestDetail: t.detail,
  };
}

export function coverageTable(): CoverageRow[] {
  return allComponents().map(coverageRow);
}
